// === Tab: mySketch ===
//let to reproduce Arrival´s let Lenguage.

ArrayList<Particle> system;

let radius = 200;
let counter;
let a,b;

class Particle{
  posX;
  posY;
	angle;
	bool excitable;
	dirX;
	dirY;

  constructor(x, y, i){
  posX=x;
  posY=y;
	angle = i;
	excitable=false;
	dirX =random(-1,1)*0.1;
  dirY =random(-1,1)*0.1;
  }

  function display(){
    noStroke();
    fill(0,0,0,40);
    ellipse(posX,posY,4,4);}

  IsIN(){
    let True = true;
    let False = false;
    if((posX > width) || (posX < 0)){
      return False;}
    if((posY > height) || (posY < 0)){
      return False;}
     else{
       return True;}
  }


  function move(){
    dirX = dirX+random(-0.1,0.1);
    dirY = dirY+random(-0.1,0.1);
    posX = posX + dirX;
    posY = posY + dirY;   
  }
}

function poblateregion(system){
	a = random(0,360);
	b = a+random(90,180);
	for(i = a ; i < b ; i++){
    angle = i*Math.PI/180;
    x = cos(angle)*radius+width/2;
    y = sin(angle)*radius+height/2;
    system.add(new Particle(x,y,i));
  }
}

function exciteregion(system){
	a = random(0,360);
	b = a+random(10,40);
	for (let ps of system){
		if( ps.angle > a && ps.angle < b) 
				ps.excitable=true;
  }
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL)
	init()
}

function init(){
	background(255);
  system = new ArrayList<Particle>();
	for(i = 0 ; i < 3 ; i++){
			poblateregion(system);
	}
	for(i = 0 ; i < 5 ; i++){
			exciteregion(system);
	}
	counter = 0;
}

function draw() {
  for (let ps of system){
		if(ps.excitable && counter < 100){
			ps.move();
		}
    if(ps.IsIN()){
     ps.display();
    }
  }
	counter++;
	if(counter > 150){
		init()
	}
}

function mouseClicked() {
	init()
}

